function cevniShow(k,b){document.querySelectorAll('#cevniPage .cevniSection').forEach(x=>x.classList.remove('active'));let e=document.getElementById('cevni'+k[0].toUpperCase()+k.slice(1));if(e)e.classList.add('active');document.querySelectorAll('#cevniPage>.cevniNav button').forEach(x=>x.classList.remove('active'));if(b)b.classList.add('active');if(k==='scenarios')cevniRenderScenario(0);}
function cevniDone(){try{return JSON.parse(localStorage.getItem('pwCevniDone')||'[]')}catch(e){return []}}
function cevniSaveDone(a){localStorage.setItem('pwCevniDone',JSON.stringify(a));cevniRenderModules()}
function cevniCurrentModule(){let d=cevniDone();for(let i=0;i<CEVNI_MODULES.length;i++)if(!d.includes(i))return i;return CEVNI_MODULES.length}
function cevniModuleUnlocked(i){return cvDevMode||i<=cevniCurrentModule()||cevniDone().includes(i)}
function cevniRenderModules(){
 let d=cevniDone(),g=document.getElementById('cevniModuleGrid');if(!g)return;
 let current=cevniCurrentModule();
 g.innerHTML=CEVNI_MODULES.map((m,i)=>{let done=d.includes(i),cur=!done&&i===current,locked=!done&&!cur&&!cvDevMode;let state=done?'COMPLETE':cur?'NEXT':'MODULE '+m.n;let note=done?'✓ Reviewed':cur?'Ready to continue':locked?'Course Mode locked':'Available';return `<button class="cvStage ${done?'done':''} ${cur?'current':''} ${locked?'locked':''}" ${locked?'disabled aria-disabled="true"':''} onclick="cevniOpenLesson(${i},0)"><span>${state}</span><b>${m.title}</b><small>${note}</small></button>`}).join('');
 let p=document.getElementById('cevniProgressText');if(p)p.textContent=`${d.length} / 9 MODULES REVIEWED • ${CEVNI_MODULES.reduce((n,m)=>n+m.sections.length,0)} TEACHING BRIEFINGS`;
}
function cevniOpenLesson(i,step=0){
 if(!cevniModuleUnlocked(i))return;
 let m=CEVNI_MODULES[i],a=document.getElementById('cevniLessonArea');if(!a)return;
 let total=m.sections.length,atCheck=step>=total,shown=Math.min(step+1,total),pct=atCheck?100:Math.round(shown/(total+1)*100);
 if(atCheck){
  a.innerHTML=`<div class="cvLessonShell"><div class="cvLessonTop"><div><div class="ver">MODULE ${m.n} • KNOWLEDGE CHECK</div><h2>${m.title}</h2><p class="cevniLead">Complete the module check after reviewing all ${total} teaching briefings.</p></div><div class="cvLessonCounter">CHECK • ${i+1} / 9</div></div><div class="cvLessonProgress"><i style="width:100%"></i></div><div class="cevniKnowledge cvKnowledgeOnly"><div class="ver">KNOWLEDGE CHECK • REQUIRED BEFORE REVIEW</div><h3>${m.check[0]}</h3><div class="cevniAnswers">${m.check[1].map((x,j)=>`<button onclick="cevniLessonAnswer(this,${j===m.check[2]},${i})">${String.fromCharCode(65+j)} • ${x}</button>`).join('')}</div><div id="cevniLessonFeedback"></div></div><div class="cvLessonNav"><button class="cvClose" onclick="cevniCloseLesson()">CLOSE</button><span></span><button class="cvBack" onclick="cevniOpenLesson(${i},${Math.max(0,total-1)})">← LAST BRIEFING</button></div></div>`;
 }else{
  let x=m.sections[step];
  a.innerHTML=`<div class="cvLessonShell"><div class="cvLessonTop"><div><div class="ver">MODULE ${m.n} • GUIDED LEARNING</div><h2>${m.title}</h2><p class="cevniLead">${m.desc}</p></div><div class="cvLessonCounter">BRIEFING ${shown} / ${total}</div></div><div class="cvLessonProgress"><i style="width:${pct}%"></i></div><article class="cvBriefingCard"><span class="cvBriefNo">TEACHING BRIEFING ${String(shown).padStart(2,'0')}</span><h3>${x[0]}</h3><p>${x[1]}</p></article><div class="cvLessonNav"><button class="cvClose" onclick="cevniCloseLesson()">CLOSE</button>${step>0?`<button class="cvBack" onclick="cevniOpenLesson(${i},${step-1})">← PREVIOUS</button>`:'<span></span>'}<button class="cvNext" onclick="cevniOpenLesson(${i},${step+1})">${step===total-1?'MODULE CHECK →':'NEXT BRIEFING →'}</button></div><div class="cvCourseFooter"><span>CEVNI course content remains separate from the COLREG pathway.</span><span>Module ${i+1} of 9</span></div></div>`;
 }
 a.scrollIntoView({behavior:'smooth',block:'start'});
}
function cevniCloseLesson(){let a=document.getElementById('cevniLessonArea');if(a)a.innerHTML=''}
function cevniLessonAnswer(b,ok,i){let box=document.getElementById('cevniLessonFeedback');document.querySelectorAll('#cevniLessonArea .cevniAnswers button').forEach(x=>x.disabled=true);b.classList.add(ok?'good':'bad');if(ok){box.innerHTML=`<div class="cevniPass"><b>UNDERSTOOD</b><p>Module check passed. Mark it reviewed and continue when ready.</p><button onclick="cevniMark(${i})">MARK REVIEWED & CONTINUE →</button></div>`}else{box.innerHTML=`<div class="cevniRetry"><b>REVIEW THAT POINT</b><p>The module stays open. Return to the teaching briefings, then retry the check.</p><button onclick="cevniOpenLesson(${i},0)">REVIEW MODULE</button><button onclick="cevniOpenLesson(${i},${CEVNI_MODULES[i].sections.length})">RETRY MODULE CHECK</button></div>`}}
function cevniMark(i){let d=cevniDone();if(!d.includes(i))d.push(i);cevniSaveDone(d);if(i<8)cevniOpenLesson(i+1,0);else document.getElementById('cevniLessonArea').innerHTML='<div class="cevniLesson"><h2>Pathway review complete.</h2><p>Continue through Signs, Sound and Practical, then take the 30-question mock.</p></div>'}
function cevniResetProgress(){if(confirm('Reset CEVNI pathway progress only?')){localStorage.removeItem('pwCevniDone');cevniRenderModules();cevniCloseLesson()}}
function cevniRenderSigns(){let g=document.getElementById('cevniSignGrid');if(!g)return;g.innerHTML=CEVNI_SIGNS.map(s=>`<div class="cevniSign"><div class="cevniPlate">${s.svg}</div><span class="cevniSignCode">ANNEX 7 • ${s.code}</span><span class="cevniSignMeaning">${s.meaning}</span><p class="cevniSignNote">${s.note}</p></div>`).join('')}
const CEVNI_WAV_AUDIO=[
  'data:audio/wav;base64,',
  'data:audio/wav;base64,',
  'data:audio/wav;base64,',
  'data:audio/wav;base64,',
  'data:audio/wav;base64,',
  'data:audio/wav;base64,',
  'data:audio/wav;base64,',
  'data:audio/wav;base64,',
  'data:audio/wav;base64,',
  'data:audio/wav;base64,',
  'data:audio/wav;base64,',
  'data:audio/wav;base64,',
  'data:audio/wav;base64,',
  'data:audio/wav;base64,',
  'data:audio/wav;base64,'
];
// CEVNI Sound Lab 1.47.6: pre-rendered WAV files. No Web Audio / AudioContext dependency.
// iPad/Safari plays a normal HTMLAudioElement directly from the user's PLAY tap.
let cevniSoundBusy=false;
let cevniActiveAudio=null;
function cevniPlayIndex(i,btn){
 if(cevniSoundBusy)return;
 const st=document.getElementById('cevniAudioStatus');
 try{
   if(cevniActiveAudio){try{cevniActiveAudio.pause()}catch(_){}}
   const a=new Audio(CEVNI_WAV_AUDIO[i]);
   cevniActiveAudio=a;
   a.preload='auto';
   a.volume=1.0;
   cevniSoundBusy=true;
   if(btn)btn.textContent='PLAYING…';
   if(st)st.textContent='PLAYING • embedded WAV horn audio';
   const reset=()=>{cevniSoundBusy=false;if(btn)btn.textContent='▶ PLAY';if(st)st.textContent='READY • embedded WAV horn audio';};
   a.onended=reset;
   a.onerror=()=>{reset();if(st)st.textContent='AUDIO ERROR • iPad could not play embedded WAV';};
   const pr=a.play();
   if(pr&&typeof pr.catch==='function')pr.catch(e=>{reset();if(st)st.textContent='AUDIO BLOCKED • '+(e&&e.message?e.message:'playback failed');});
 }catch(e){
   cevniSoundBusy=false;
   if(btn)btn.textContent='▶ PLAY';
   if(st)st.textContent='AUDIO ERROR • '+(e&&e.message?e.message:'Could not start WAV');
 }
}
function cevniPatternBars(seq){return '<span class="cvPattern" aria-label="sound pattern">'+seq.map((d,i)=>'<i class="'+(d<0.5?'vs':d>=3?'long':'short')+'"></i>').join('<em></em>')+'</span>'}
function cevniRenderSounds(){
 let a=document.getElementById('cevniSoundRows');if(!a)return;
 a.innerHTML=`<div id="cevniAudioStatus" class="cevniAudioStatus">READY • embedded WAV horn audio • visual bars are generated from the same timing sequence as the recording.</div>`+CEVNI_SOUNDS.map((s,i)=>`<div class="cevniAudioRow"><div class="cvSoundText"><b>${s[0]}</b>${cevniPatternBars(s[3])}<br><small>${s[2]}</small></div><button onclick="cevniPlayIndex(${i},this)">▶ PLAY</button></div>`).join('');
}
function cevniScenarioVisual(s){let v={rules:'<div class="cvMap"><b>LOCAL NOTICE</b><span>CEVNI + WATERWAY RULES</span><i>?</i></div>',sign:'<div class="cvSign"><div>↑</div><b>MANDATORY</b><span>FOLLOW DISPLAYED DIRECTION</span></div>',lock:'<div class="cvLock"><i></i><i></i><b>LOCK</b><span>VHF • LIGHTS • INSTRUCTIONS</span></div>',ais:'<div class="cvAIS"><i>▲</i><i>▲</i><b>AIS</b><span>VERIFY WITH LOOKOUT</span></div>'};return `<div class="cevniScenarioVisual ${s.visual}">${v[s.visual]}</div>`}
function cevniRenderScenario(i){let s=CEVNI_SCENARIOS[i%CEVNI_SCENARIOS.length],a=document.getElementById('cevniScenarioArea');a.innerHTML=`<div class="cevniScenario">${cevniScenarioVisual(s)}<div><small>SCENARIO ${i+1} / ${CEVNI_SCENARIOS.length} • ${s.label}</small><div class="cevniQ">${s.q}</div><div class="cevniAnswers">${s.a.map((x,j)=>`<button onclick="cevniScenarioAnswer(this,${j===s.c},${i})">${String.fromCharCode(65+j)} • ${x}</button>`).join('')}</div><div id="cevniScenarioDebrief"></div></div></div>`}
function cevniScenarioAnswer(b,ok,i){b.classList.add(ok?'good':'bad');document.getElementById('cevniScenarioDebrief').innerHTML=`<div class="cevniMockResult"><b>${ok?'CORRECT':'REASSESS'}</b><p>${CEVNI_SCENARIOS[i].e}</p><button onclick="cevniRenderScenario(${(i+1)%CEVNI_SCENARIOS.length})">NEXT SCENARIO →</button></div>`}
let cvMock=[];let cvMi=0;let cvScore=0;function cevniQuestionBank(){return CEVNI_QBASE.map(x=>{let opts=x[1].map((t,i)=>({t,ok:i===x[2]}));for(let i=opts.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[opts[i],opts[j]]=[opts[j],opts[i]]}return [x[0],opts.map(o=>o.t),opts.findIndex(o=>o.ok)]})}
function cevniStartMock(){cvMock=cevniQuestionBank().sort(()=>Math.random()-.5).slice(0,30);cvMi=0;cvScore=0;cevniRenderMock()}
function cevniRenderMock(){let a=document.getElementById('cevniMockArea');if(cvMi>=cvMock.length){let pct=Math.round(cvScore/cvMock.length*100);a.innerHTML=`<div class="cevniMockResult"><h2>${cvScore} / ${cvMock.length} • ${pct}%</h2><p>Independent Project Watch training result. Review weak areas against the CEVNI modules and applicable official/local rules.</p><button onclick="cevniStartMock()">NEW MOCK</button></div>`;return}let q=cvMock[cvMi];a.innerHTML=`<div class="cevniProgress"><b>QUESTION ${cvMi+1} / 30</b><span>SCORE ${cvScore}</span></div><div class="cevniQ">${q[0]}</div><div class="cevniAnswers">${q[1].map((x,j)=>`<button onclick="cevniMockAnswer(this,${j===q[2]})">${String.fromCharCode(65+j)} • ${x}</button>`).join('')}</div>`}
function cevniMockAnswer(b,ok){if(ok)cvScore++;document.querySelectorAll('#cevniMockArea .cevniAnswers button').forEach(x=>x.disabled=true);b.classList.add(ok?'good':'bad');setTimeout(()=>{cvMi++;cevniRenderMock()},450)}
let cvDevMode=false,cvDevIndex=0;
function cevniDevItems(){let x=[];CEVNI_MODULES.forEach((m,i)=>x.push({type:'lesson',i,label:`MODULE ${m.n} CHECK`}));CEVNI_SCENARIOS.forEach((q,i)=>x.push({type:'scenario',i,label:`PRACTICAL ${i+1}/${CEVNI_SCENARIOS.length}`}));CEVNI_QBASE.forEach((q,i)=>x.push({type:'mock',i,label:`MOCK ${i+1}/${CEVNI_QBASE.length}`}));return x}
function cevniDevToggle(){cvDevMode=!cvDevMode;let b=document.getElementById('cevniDevToggle'),bar=document.getElementById('cevniDevBar');b.classList.toggle('on',cvDevMode);b.textContent=cvDevMode?'🧪 TEST MODE ON':'🧪 TEST MODE';bar.hidden=!cvDevMode;if(cvDevMode){cevniRenderModules();cvDevIndex=0;cevniDevGo()}else{cevniRenderModules();document.querySelectorAll('.cevniDevCorrect,.cevniDevWrong').forEach(x=>x.classList.remove('cevniDevCorrect','cevniDevWrong'))}}
function cevniDevGo(){if(!cvDevMode)return;let all=cevniDevItems();cvDevIndex=(cvDevIndex+all.length)%all.length;let d=all[cvDevIndex],st=document.getElementById('cevniDevStatus');st.textContent=`${cvDevIndex+1}/${all.length} • ${d.label}`;if(d.type==='lesson'){cevniShow('course');cevniOpenLesson(d.i,CEVNI_MODULES[d.i].sections.length)}else if(d.type==='scenario'){cevniShow('scenarios');cevniRenderScenario(d.i)}else{cevniShow('mock');cvMock=cevniQuestionBank();cvMi=d.i;cvScore=0;cevniRenderMock()}setTimeout(cevniDevReveal,30)}
function cevniDevPrev(){if(!cvDevMode)return;cvDevIndex--;cevniDevGo()}
function cevniDevNext(){if(!cvDevMode)return;cvDevIndex++;cevniDevGo()}
function cevniDevReset(){cvDevIndex=0;cvScore=0;cvMock=[];localStorage.removeItem('pwCevniDone');cevniRenderModules();cevniDevGo()}
function cevniDevReveal(){if(!cvDevMode)return;document.querySelectorAll('.cevniDevCorrect,.cevniDevWrong').forEach(x=>x.classList.remove('cevniDevCorrect','cevniDevWrong'));let all=cevniDevItems(),d=all[cvDevIndex],root=null,correct=-1;if(d.type==='lesson'){root=document.querySelector('#cevniLessonArea .cevniAnswers');correct=CEVNI_MODULES[d.i].check[2]}else if(d.type==='scenario'){root=document.querySelector('#cevniScenarioArea .cevniAnswers');correct=CEVNI_SCENARIOS[d.i].c}else{root=document.querySelector('#cevniMockArea .cevniAnswers');correct=(cvMock[d.i]||CEVNI_QBASE[d.i])[2]}if(root){[...root.querySelectorAll('button')].forEach((b,i)=>b.classList.add(i===correct?'cevniDevCorrect':'cevniDevWrong'));let old=root.parentElement.querySelector('.cevniDevTag');if(old)old.remove();let tag=document.createElement('div');tag.className='cevniDevTag';tag.textContent=`TEST ANSWER: ${String.fromCharCode(65+correct)} • ${root.querySelectorAll('button')[correct]?.textContent.replace(/^[A-Z]\s*•\s*/,'')||''}`;root.after(tag)}}
function cevniInit(){document.getElementById('cevniCourseTitle').textContent=PW_CEVNI_CONFIG.courseName;document.getElementById('cvCfgCourse').textContent=PW_CEVNI_CONFIG.courseName;document.getElementById('cvCfgProvider').textContent=PW_CEVNI_CONFIG.provider;document.getElementById('cvCfgExam').textContent=PW_CEVNI_CONFIG.assessmentName;cevniRenderModules();cevniRenderSigns();cevniRenderSounds()}
(function(){let old=window.showModule;if(old)window.showModule=function(name,btn){old(name,btn);if(name==='cevni')setTimeout(cevniInit,0)};window.PROJECT_WATCH_BUILD='1.47.10-CEVNI-UNIFORM-SCAFFOLD';let vb=document.getElementById('pwVisibleBuild');if(vb)vb.textContent='BUILD 1.47.10-CEVNI-UNIFORM-SCAFFOLD';})();
